// Example: method to find highest value in an array
class ScoreTracker {
  getHighestScore() {
    if (this.scores.length === 0) return null;
    let highest = this.scores[0];
    for (let score of this.scores) {
      if (score > highest) highest = score;
    }
    return highest;
  }
}

